//! FEFF atomic-configuration default occupation tables.
//!
//! The data below is a mechanical Rust transcription of FEFF10
//! `COMMON/m_config.f90` default `iocc9`, `ival9`, `ispn9`,
//! `iocc7`, and `ival7` rows. The public helper keeps table selection
//! separate from `orbital_configuration`, which applies the `getorb`
//! core-hole, screening, ionicity, and valence-freezing rules.

use ndarray::Array1;

use crate::{Real, atomic::AtomicError};

use super::FEFF_ORBITAL_SLOT_COUNT;

const FEFF_CONFIGURATION_ATOMIC_COUNT: usize = 139;

/// FEFF default electron-configuration recipe.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum FeffConfigurationRecipe {
    /// FEFF9 default configuration tables.
    Feff9,
    /// FEFF7 compatibility configuration tables.
    Feff7,
}

/// One 40-slot FEFF default configuration row set.
#[derive(Debug, Clone, PartialEq)]
pub struct FeffDefaultConfigurationRows {
    /// Occupation row, FEFF `iocc`.
    pub occupations: Array1<Real>,
    /// Valence occupation row, FEFF `ival`.
    pub valence_occupations: Array1<Real>,
    /// Spin marker row, FEFF `ispn`. FEFF7 rows are zero-filled.
    pub spin_occupations: Array1<Real>,
}

/// Return FEFF's default 40-slot configuration rows for `atomic_number`.
pub fn feff_default_configuration_rows(
    atomic_number: usize,
    recipe: FeffConfigurationRecipe,
) -> Result<FeffDefaultConfigurationRows, AtomicError> {
    if atomic_number == 0 {
        return Err(AtomicError::InvalidAtomicNumber { z: atomic_number });
    }
    let index = atomic_number - 1;
    if index >= FEFF_CONFIGURATION_ATOMIC_COUNT {
        return Err(AtomicError::InvalidAtomicNumber { z: atomic_number });
    }
    let (occupations, valence_occupations, spin_occupations) = match recipe {
        FeffConfigurationRecipe::Feff9 => (
            &FEFF9_OCCUPATIONS[index],
            &FEFF9_VALENCE_OCCUPATIONS[index],
            &FEFF9_SPIN_OCCUPATIONS[index],
        ),
        FeffConfigurationRecipe::Feff7 => (
            &FEFF7_OCCUPATIONS[index],
            &FEFF7_VALENCE_OCCUPATIONS[index],
            &FEFF7_SPIN_OCCUPATIONS[index],
        ),
    };

    Ok(FeffDefaultConfigurationRows {
        occupations: Array1::from_vec(occupations.to_vec()),
        valence_occupations: Array1::from_vec(valence_occupations.to_vec()),
        spin_occupations: Array1::from_vec(spin_occupations.to_vec()),
    })
}

static FEFF7_SPIN_OCCUPATIONS: [[Real; FEFF_ORBITAL_SLOT_COUNT]; FEFF_CONFIGURATION_ATOMIC_COUNT] =
    [[0.0; FEFF_ORBITAL_SLOT_COUNT]; FEFF_CONFIGURATION_ATOMIC_COUNT];

